insert into public.lessons (lesson_id, language, level, chapter_number, slug, title, goal_vocabulary_md, status, "order") values ('public/curriculum/advanced/advanced_exercises_23.md', 'sanskrit', 'advanced', 16, 'advanced-exercises-23', 'advanced_exercises_23', '1. स: शालां गच्छति, पाठं पठति | Saḥ śālāṁ gacchati, pāṭhaṁ paṭhati.
   स: शालां गत्वा पाठं पठति | Saḥ śālāṁ gatvā pāṭhaṁ paṭhati.
   ते कार्यं कुर्वन्ति, श्रान्ताः भवन्ति | Te kāryaṁ kurvanti, śrāntāḥ bhavanti.

