insert into public.lessons (lesson_id, language, level, chapter_number, slug, title, goal_vocabulary_md, status, "order") values ('curriculum/numbers/number_practice.md', 'sanskrit', 'numbers', 135, 'sanskrit-numbers-and-practice-exercise', 'Sanskrit Numbers and Practice Exercise', '## Sanskrit Numbers and Practice Exercise

### Numbers (11-40)

**Instructions:** *Etāḥ saṅkhyāḥ uccaiḥ paṭhatu* - Read these numbers aloud.


