insert into public.lessons (lesson_id, language, level, chapter_number, slug, title, goal_vocabulary_md, status, "order") values ('curriculum/vocabulary/kitchen_utensils.md', 'sanskrit', 'vocabulary', 144, '4-1-paakashaala-sambandhi-vastuni-kitchen-cooking-utensils', '4.1 Paakashaala Sambandhi Vastuni - kitchen/cooking utensils', '# 4.1 Paakashaala Sambandhi Vastuni - kitchen/cooking utensils 

| Sanskrit | Transliterated | Translated | Comments |
|----------|---------------|------------|-----------|
| चषक: | Caṣakaḥ | Cup/Glass | Drinking glass with decorative pattern |
| चमस: | Camasaḥ | Spoon | A simple serving spoon |
| घट: | Ghataḥ | Pot/Vessel | A wide-mouthed vessel or pot |
| करण्डक: | Karaṇḍakaḥ | Container/Jar | Storage container with lid |
| पात्रम् | Pātram | Vessel/Pan | Cooking pot with handle |
| मिश्रकम् | Miśrakam | Mixer/Blender | Electric blender/mixer |
